import flask


def test_app_template_filter_bare_decorator(app):
    @app.template_filter
    def reverse_text(value):
        return value[::-1]

    assert app.jinja_env.filters["reverse_text"] is reverse_text
    assert app.jinja_env.filters["reverse_text"]("abcd") == "dcba"


def test_app_template_filter_bare_decorator_returns_original(app):
    def reverse_text(value):
        return value[::-1]

    assert app.template_filter(reverse_text) is reverse_text
    assert app.jinja_env.filters["reverse_text"] is reverse_text


def test_app_template_filter_without_parentheses(app):
    @app.template_filter()
    def upper_text(value):
        return value.upper()

    assert app.jinja_env.filters["upper_text"] is upper_text
    assert app.jinja_env.filters["upper_text"]("abc") == "ABC"


def test_app_template_filter_with_none_name(app):
    @app.template_filter(None)
    def lower_text(value):
        return value.lower()

    assert app.jinja_env.filters["lower_text"] is lower_text


def test_app_template_filter_with_positional_name(app):
    @app.template_filter("public_name")
    def reverse_text(value):
        return value[::-1]

    assert app.jinja_env.filters["public_name"] is reverse_text
    assert app.jinja_env.filters["public_name"]("abcd") == "dcba"


def test_app_template_filter_with_keyword_name(app):
    @app.template_filter(name="public_name")
    def reverse_text(value):
        return value[::-1]

    assert app.jinja_env.filters["public_name"] is reverse_text
    assert app.jinja_env.filters["public_name"]("abcd") == "dcba"


def test_app_template_test_bare_decorator(app):
    @app.template_test
    def is_even(value):
        return value % 2 == 0

    assert app.jinja_env.tests["is_even"] is is_even
    assert app.jinja_env.tests["is_even"](2)


def test_app_template_test_bare_decorator_returns_original(app):
    def is_even(value):
        return value % 2 == 0

    assert app.template_test(is_even) is is_even
    assert app.jinja_env.tests["is_even"] is is_even


def test_app_template_test_with_positional_name(app):
    @app.template_test("boolean")
    def is_boolean(value):
        return isinstance(value, bool)

    assert app.jinja_env.tests["boolean"] is is_boolean
    assert app.jinja_env.tests["boolean"](False)


def test_app_template_global_bare_decorator(app):
    @app.template_global
    def get_answer():
        return 42

    assert app.jinja_env.globals["get_answer"] is get_answer
    assert app.jinja_env.globals["get_answer"]() == 42


def test_app_template_global_bare_decorator_returns_original(app):
    def get_answer():
        return 42

    assert app.template_global(get_answer) is get_answer
    assert app.jinja_env.globals["get_answer"] is get_answer


def test_blueprint_app_template_filter_bare_decorator(app):
    bp = flask.Blueprint("bp", __name__)

    @bp.app_template_filter
    def reverse_text(value):
        return value[::-1]

    # Deferred until the blueprint is registered on an application.
    assert "reverse_text" not in app.jinja_env.filters

    app.register_blueprint(bp, url_prefix="/py")
    assert app.jinja_env.filters["reverse_text"] is reverse_text
    assert app.jinja_env.filters["reverse_text"]("abcd") == "dcba"


def test_blueprint_app_template_test_bare_decorator(app):
    bp = flask.Blueprint("bp", __name__)

    @bp.app_template_test
    def is_even(value):
        return value % 2 == 0

    app.register_blueprint(bp, url_prefix="/py")
    assert app.jinja_env.tests["is_even"] is is_even
    assert app.jinja_env.tests["is_even"](2)


def test_blueprint_app_template_global_bare_decorator(app):
    bp = flask.Blueprint("bp", __name__)

    @bp.app_template_global
    def get_answer():
        return 42

    app.register_blueprint(bp, url_prefix="/py")
    assert app.jinja_env.globals["get_answer"] is get_answer
    assert app.jinja_env.globals["get_answer"]() == 42
